//初始化调用ajax 用于地址服务
function uf_creatXMLHttpRequest() {
 var ajax;
 if (window.ActiveXObject) {
 return ajax = new ActiveXObject("Microsoft.XMLHTTP");
 } else if (window.XMLHttpRequest) {
 return ajax = new XMLHttpRequest();
 }

}
